const HAZE = 0xbcb19b;
const REFL = []; // grupos de helicópteros que se reflejan en el agua (reflFrame)
const scene = new T.Scene();
scene.autoUpdate = false; // las matrices las refresco a mano una vez por frame, justo antes de pintar
scene.background = new T.Color(HAZE);
scene.fog = new T.Fog(HAZE, 92, 150);
const cam = new T.OrthographicCamera(-1, 1, 1, -1, 0.1, 400);
const hemi = new T.HemisphereLight(0xfff4e2, 0x8a7a5e, 0.72);
scene.add(hemi);
const sun = new T.DirectionalLight(0xffd9a2, 1.0);
sun.position.set(W / 2 - 30, 40, H / 2 + 24);
sun.target.position.set(W / 2, 0, H / 2);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
Object.assign(sun.shadow.camera, { left: -50, right: 50, top: 50, bottom: -50, near: 1, far: 160 });
sun.shadow.bias = -0.0016;
sun.shadow.camera.layers.mask = 3; // la cámara de sombras también ve la capa 1 (zonas fuera de pantalla)
scene.add(sun);
scene.add(sun.target);

const geoC = {},
  matC = {};
const bgeo = (w, h, d) => {
  const k = w + '|' + h + '|' + d;
  return geoC[k] || (geoC[k] = new T.BoxGeometry(w, h, d));
};
const lmat = c => matC[c] || (matC[c] = new T.MeshPhongMaterial({ color: c, specular: 0x000000, shininess: 1 }));
function box(w, h, d, col, x, y, z, parent, shadow) {
  const m = new T.Mesh(bgeo(w, h, d), lmat(col));
  m.position.set(x, y, z);
  if (shadow !== false) {
    m.castShadow = true;
    m.receiveShadow = true;
  }
  parent.add(m);
  return m;
}
